/**
 * SummaryPanel — "Race Engineer's Notes": the AI explanation of the current
 * setup, generated by the user's local Claude Code CLI.
 *
 * Trigger logic (debounce on param changes / focus changes) lives in
 * hooks/useDebouncedSummary, mounted once in App — this panel only renders
 * the lifecycle owned by useSummaryStore and offers manual actions
 * (focus, regenerate, copy, inspect prompt).
 */
import { useEffect, useRef, useState } from 'react';
import { Check, Copy, FileSearch2, RefreshCw, Sparkles } from 'lucide-react';
import type { SummaryFocus } from '../../types';
import { useSummaryStore } from '../../store/useSummaryStore';
import { Panel } from '../layout/Panel';
import { Toggle } from '../common/Toggle';
import { IconButton } from '../common/IconButton';
import { Badge } from '../common/Badge';
import { MarkdownLite } from './MarkdownLite';

const FOCUS_OPTIONS: Array<{ value: SummaryFocus; label: string }> = [
  { value: 'overview', label: 'Overview' },
  { value: 'handling', label: 'Handling' },
  { value: 'comfort', label: 'Comfort' },
  { value: 'tradeoffs', label: 'Tradeoffs' },
  { value: 'stance', label: 'Stance' },
];

const SKELETON_WIDTHS = [92, 100, 78, 45] as const;

export function SummaryPanel() {
  const text = useSummaryStore((s) => s.text);
  const loading = useSummaryStore((s) => s.loading);
  const offline = useSummaryStore((s) => s.offline);
  const cached = useSummaryStore((s) => s.cached);
  const error = useSummaryStore((s) => s.error);
  const promptUsed = useSummaryStore((s) => s.promptUsed);
  const tookMs = useSummaryStore((s) => s.tookMs);
  const focus = useSummaryStore((s) => s.focus);
  const setFocus = useSummaryStore((s) => s.setFocus);
  const setInspectorOpen = useSummaryStore((s) => s.setInspectorOpen);

  const [copied, setCopied] = useState(false);
  const copyTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(
    () => () => {
      if (copyTimer.current) clearTimeout(copyTimer.current);
    },
    [],
  );

  const handleCopy = () => {
    if (!text) return;
    navigator.clipboard
      .writeText(text)
      .then(() => {
        setCopied(true);
        if (copyTimer.current) clearTimeout(copyTimer.current);
        copyTimer.current = setTimeout(() => setCopied(false), 1500);
      })
      .catch(() => {
        /* clipboard blocked — keep the Copy icon, nothing to flash */
      });
  };

  const retry = () => void useSummaryStore.getState().request();

  return (
    <Panel
      title="Race Engineer's Notes"
      className="w-full"
      actions={
        <>
          {/* Changing focus refires the summary via useDebouncedSummary in App. */}
          <Toggle<SummaryFocus>
            value={focus}
            options={FOCUS_OPTIONS}
            onChange={setFocus}
            ariaLabel="Summary focus"
          />
          <IconButton label="Regenerate summary" onClick={retry}>
            <RefreshCw size={14} className={loading ? 'motion-safe:animate-spin' : ''} />
          </IconButton>
          <IconButton
            label={copied ? 'Copied to clipboard' : 'Copy summary'}
            onClick={handleCopy}
            disabled={!text}
          >
            {copied ? <Check size={14} /> : <Copy size={14} />}
          </IconButton>
          <IconButton
            label="Inspect the exact prompt sent to Claude Code"
            onClick={() => setInspectorOpen(true)}
            disabled={!promptUsed}
          >
            <FileSearch2 size={14} />
          </IconButton>
        </>
      }
    >
      {/* Stable min-height so the panel doesn't jump between states. */}
      <div className="min-h-[120px]" aria-live="polite">
        {loading ? (
          <div className="space-y-2.5" aria-busy="true">
            {SKELETON_WIDTHS.map((w) => (
              <div key={w} className="skeleton h-3.5 rounded" style={{ width: `${w}%` }} />
            ))}
            <div className="flex items-center gap-1.5 pt-1 text-[12px] text-ink-3">
              <Sparkles size={13} aria-hidden="true" />
              <span>Consulting Claude Code…</span>
            </div>
          </div>
        ) : error && !offline ? (
          <div className="flex flex-wrap items-center gap-2">
            <Badge tone="danger">{error}</Badge>
            <button
              type="button"
              onClick={retry}
              className="rounded-md border border-edge px-2 py-0.5 text-[12px] font-medium text-ink-2 transition-colors duration-150 hover:bg-surface-2 hover:text-ink"
            >
              Retry
            </button>
          </div>
        ) : text ? (
          <>
            <MarkdownLite text={text} />
            <div className="mt-3 flex flex-wrap items-center gap-2">
              {offline && <Badge tone="warn">Offline explanation (Claude Code not detected)</Badge>}
              {cached && <Badge tone="neutral">cached</Badge>}
              {tookMs > 0 && !offline && (
                <span className="mono text-[11px] text-ink-3">
                  {(tookMs / 1000).toFixed(1)}s via local claude
                </span>
              )}
            </div>
            {offline && (
              <p className="mt-2 text-[12px] text-ink-3">
                To enable AI summaries: install Claude Code (npm i -g @anthropic-ai/claude-code),
                log in, and restart the SuspensionLab server.
              </p>
            )}
          </>
        ) : (
          <p className="text-[12px] text-ink-3">
            Waiting for the first summary — adjust any parameter to generate one.
          </p>
        )}
      </div>
    </Panel>
  );
}
